async function renderMotionClip(imageUrl:string,motion:Motion,atmosphere:Exclude<Atmosphere,"auto">,seed:number,seconds:number){
 if(!("MediaRecorder"in window))throw new Error("trình duyệt chưa hỗ trợ dựng WebM");
 const image=new Image();image.src=imageUrl;await image.decode();
 const width=1280,height=720,canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;
 const context=canvas.getContext("2d");if(!context)throw new Error("không mở được bộ dựng hình");
 const stream=canvas.captureStream(30),mime=MediaRecorder.isTypeSupported("video/webm;codecs=vp9")?"video/webm;codecs=vp9":MediaRecorder.isTypeSupported("video/webm;codecs=vp8")?"video/webm;codecs=vp8":"video/webm",recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5_000_000}),chunks:Blob[]=[];
 const result=new Promise<Blob>((resolve,reject)=>{recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data)};recorder.onerror=()=>reject(new Error("bộ dựng video bị gián đoạn"));recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());resolve(new Blob(chunks,{type:mime}))}});
 const cover=(scale:number,offsetX:number,offsetY:number)=>{const base=Math.max(width/image.naturalWidth,height/image.naturalHeight)*scale,drawWidth=image.naturalWidth*base,drawHeight=image.naturalHeight*base;context.drawImage(image,(width-drawWidth)/2+offsetX,(height-drawHeight)/2+offsetY,drawWidth,drawHeight)};
 const started=performance.now();recorder.start(250);
 const frame=(now:number)=>{const progress=Math.min(1,(now-started)/(seconds*1000)),phase=progress*Math.PI*2;context.clearRect(0,0,width,height);context.save();context.filter="blur(24px) brightness(55%) saturate(82%)";cover(1.18,0,0);context.restore();context.save();cover(1.04,0,0);context.restore();drawCinematicLight(context,width,height,phase,seed,motion!=="still");drawMotionAtmosphere(context,width,height,atmosphere,progress,seed);const shade=context.createLinearGradient(0,0,0,height);shade.addColorStop(0,"rgba(4,5,12,.18)");shade.addColorStop(.62,"rgba(4,5,12,0)");shade.addColorStop(1,"rgba(4,5,12,.42)");context.fillStyle=shade;context.fillRect(0,0,width,height);if(progress<1)requestAnimationFrame(frame);else recorder.stop()};requestAnimationFrame(frame);return result;
}

function drawCinematicLight(context:CanvasRenderingContext2D,width:number,height:number,phase:number,seed:number,enabled:boolean){
 if(!enabled)return;context.save();context.globalCompositeOperation="screen";const pulse=.55+.45*Math.sin(phase*2+seed),x=width*(.24+(seed%4)*.16),y=height*(.2+(seed%3)*.11),radius=width*.48,glow=context.createRadialGradient(x,y,0,x,y,radius);glow.addColorStop(0,`rgba(255,226,176,${.08+.14*pulse})`);glow.addColorStop(.42,`rgba(159,112,255,${.03+.06*pulse})`);glow.addColorStop(1,"rgba(0,0,0,0)");context.fillStyle=glow;context.fillRect(0,0,width,height);context.restore()
}

function drawMotionAtmosphere(context:CanvasRenderingContext2D,width:number,height:number,effect:Exclude<Atmosphere,"auto">,progress:number,seed:number){
 if(effect==="rain"){context.save();context.strokeStyle="rgba(220,239,255,.28)";context.lineWidth=1.4;for(let index=0;index<90;index++){const x=(index*97+seed*41+progress*(width+120))%(width+120)-60,y=(index*61+progress*(height+160)*2)%(height+160)-80;context.beginPath();context.moveTo(x,y);context.lineTo(x-13,y+42);context.stroke()}context.restore()}
 if(effect==="fog"){context.save();for(let index=0;index<3;index++){const phase=progress*Math.PI*2,x=width*(.15+index*.35)+Math.sin(phase+index*2.1+seed)*210,y=height*(.22+index*.27),gradient=context.createRadialGradient(x,y,15,x,y,320);gradient.addColorStop(0,"rgba(225,239,246,.18)");gradient.addColorStop(1,"rgba(225,239,246,0)");context.fillStyle=gradient;context.fillRect(x-340,y-230,680,460)}context.restore()}
 if(effect==="petals"){context.save();for(let index=0;index<26;index++){const cycles=1+index%3,x=(index*83+seed*29+Math.sin(progress*Math.PI*2+index)*55+width)%width,y=(index*137+progress*(height+120)*cycles)%(height+120)-60;context.fillStyle=`rgba(255,${175+index%50},${205+index%35},${.35+(index%5)*.09})`;context.beginPath();context.ellipse(x,y,7+(index%3),3+(index%2),progress*Math.PI*6+index,0,Math.PI*2);context.fill()}context.restore()}
 if(effect==="leaves"){context.save();for(let index=0;index<24;index++){const cycles=1+index%3,x=(index*91+seed*37+Math.sin(progress*Math.PI*2+index)*70+width)%width,y=(index*119+progress*(height+140)*cycles)%(height+140)-70;context.fillStyle=index%3===0?"rgba(214,151,54,.72)":index%3===1?"rgba(142,92,42,.7)":"rgba(112,143,63,.65)";context.beginPath();context.ellipse(x,y,10+(index%4),4+(index%3),progress*Math.PI*8+index,0,Math.PI*2);context.fill()}context.restore()}
 if(effect==="birds"){context.save();context.strokeStyle="rgba(24,27,35,.72)";context.lineWidth=3;context.lineCap="round";for(let index=0;index<7;index++){const x=((progress+index/7)%1)*(width+220)-110,y=height*(.16+(index%4)*.09)+Math.sin(progress*Math.PI*2+index)*16,wing=8+5*Math.sin(progress*Math.PI*10+index);context.beginPath();context.moveTo(x-20,y);context.quadraticCurveTo(x-10,y-wing,x,y);context.quadraticCurveTo(x+10,y-wing,x+20,y);context.stroke()}context.restore()}
 if(effect==="fireflies"){context.save();context.globalCompositeOperation="screen";for(let index=0;index<30;index++){const phase=progress*Math.PI*2,indexPhase=index*1.73+seed,x=(index*137+seed*31)%width+Math.sin(phase+indexPhase)*18,y=(index*79+seed*47)%height+Math.cos(phase*1.5+indexPhase)*12,alpha=.12+.72*Math.pow(Math.max(0,Math.sin(phase*(1+index%3)+indexPhase)),2),glow=context.createRadialGradient(x,y,0,x,y,10);glow.addColorStop(0,`rgba(255,244,142,${alpha})`);glow.addColorStop(1,"rgba(255,214,80,0)");context.fillStyle=glow;context.fillRect(x-10,y-10,20,20)}context.restore()}
}
